from solution import largest_prime_factor
import threading
import time
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def _is_prime(a: int) -> bool:
    if a < 2:
        return False
    if a % 2 == 0:
        return a == 2
    r = int(a ** 0.5)
    f = 3
    while f <= r:
        if a % f == 0:
            return False
        f += 2
    return True


def _is_composite(n: int) -> bool:
    return isinstance(n, int) and n > 1 and not _is_prime(n)


def reference_lpf(n: int) -> int:
    """Obviously-correct trial division reference model."""
    assert _is_composite(n)
    best = 1
    d = 2
    m = n
    while d * d <= m:
        if m % d == 0:
            best = d
            while m % d == 0:
                m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        best = max(best, m)
    return best


def run_with_timeout(func, arg, timeout: float):
    holder = {}
    def target():
        try:
            holder["value"] = func(arg)
        except BaseException as e:
            holder["error"] = e
    t = threading.Thread(target=target, daemon=True)
    t.start()
    t.join(timeout=timeout)
    return t.is_alive(), holder


# ---- spec examples ----

def test_spec_example_13195():
    assert largest_prime_factor(13195) == 29


def test_spec_example_2048():
    assert largest_prime_factor(2048) == 2


# ---- correctness invariants vs reference ----

def test_small_composites_match_reference():
    # exhaustive over small range: covers even/odd, prime powers, semiprimes
    for n in range(4, 300):
        if _is_composite(n):
            assert largest_prime_factor(n) == reference_lpf(n), f"n={n}"


def test_prime_powers():
    for p, e in [(2, 10), (3, 5), (5, 4), (7, 3), (11, 2), (13, 2)]:
        n = p ** e
        assert largest_prime_factor(n) == p


def test_semiprime_ordering():
    assert largest_prime_factor(6) == 3
    assert largest_prime_factor(15) == 5
    assert largest_prime_factor(21) == 7
    assert largest_prime_factor(4) == 2
    assert largest_prime_factor(9) == 3
    assert largest_prime_factor(27) == 3
    assert largest_prime_factor(49) == 7
    assert largest_prime_factor(121) == 11


def test_result_divides_n_and_is_prime():
    for n in [4, 6, 8, 9, 12, 100, 1000, 13195, 2048, 9999, 12345]:
        r = largest_prime_factor(n)
        assert isinstance(r, int)
        assert _is_prime(r), f"result {r} not prime for n={n}"
        assert n % r == 0, f"result {r} does not divide n={n}"


def test_result_is_maximal():
    for n in [4, 6, 12, 30, 60, 100, 13195, 2048, 9999, 123456]:
        r = largest_prime_factor(n)
        # no prime divisor larger than r
        for d in range(r + 1, n):
            if _is_prime(d) and n % d == 0:
                raise AssertionError(f"larger prime factor {d} exists for n={n}, got {r}")


@given(st.integers(min_value=4, max_value=2000))
def test_property_matches_reference(n):
    assume(_is_composite(n))
    assert largest_prime_factor(n) == reference_lpf(n)


@given(st.integers(min_value=4, max_value=2000))
def test_property_result_prime_and_divides(n):
    assume(_is_composite(n))
    r = largest_prime_factor(n)
    assert _is_prime(r)
    assert n % r == 0


@given(st.integers(min_value=2, max_value=200))
def test_property_prime_power(a):
    # n = p^e for small primes p, e>=2 ensures composite
    primes = [2, 3, 5, 7, 11, 13]
    for p in primes:
        n = p * p * (2 if a < 2 else a) if False else None
    # simpler: n = p^2
    import random
    # deterministic selection based on a
    p = primes[a % len(primes)]
    n = p * p
    assert largest_prime_factor(n) == p


@given(st.integers(min_value=4, max_value=500))
def test_property_idempotence_of_lpf(n):
    # lpf(n) is prime; lpf(p*q) related: multiplying by lpf doesn't change lpf
    # metamorphic: lpf(n * lpf(n)) == lpf(n)
    assume(_is_composite(n))
    r = largest_prime_factor(n)
    m = n * r
    # m is composite (multiple of r, > r since n>1)
    assert _is_composite(m) or True
    if _is_composite(m):
        assert largest_prime_factor(m) == r


@given(st.integers(min_value=2, max_value=100), st.integers(min_value=2, max_value=100))
def test_property_semiprime_max(p, q):
    # n = p*q with p,q prime => lpf = max(p,q); if p==q then =p (need composite: always composite)
    assume(_is_prime(p) and _is_prime(q))
    n = p * q
    # p*q with p,q prime is always composite (even if... p*q >1 non-prime unless... p*q composite always since p,q>=2)
    assert _is_composite(n)
    assert largest_prime_factor(n) == max(p, q)


def test_metamorphic_multiply_by_two():
    # lpf(2*p) == p for prime p > 2
    for p in [3, 5, 29, 101, 999983 % 1000 + 7]:
        # ensure prime
        if not _is_prime(p):
            continue
        n = 2 * p
        assert largest_prime_factor(n) == p


def test_touching_boundaries():
    # smallest valid inputs
    assert largest_prime_factor(4) == 2  # smallest composite
    assert largest_prime_factor(6) == 3
    assert largest_prime_factor(8) == 2


# ---- scalability / efficiency defect ----
# Correct sieve-free implementation answers these instantly.
# The O(n)-memory Python-loop sieve cannot.

def test_large_semiprime_completes_quickly():
    # 999983 is prime; n = 2 * 999983, lpf = 999983
    assert _is_prime(999983)
    n = 2 * 999983
    assert _is_composite(n)
    expected = 999983
    assert reference_lpf(n) == expected
    alive, holder = run_with_timeout(largest_prime_factor, n, timeout=1.0)
    assert not alive, f"largest_prime_factor({n}) did not finish within 1.0s (O(n) sieve defect)"
    assert "error" not in holder, f"raised {holder.get('error')!r}"
    assert holder.get("value") == expected


def test_large_power_of_two_completes_quickly():
    n = 2 ** 20  # 1048576, lpf = 2
    assert _is_composite(n)
    alive, holder = run_with_timeout(largest_prime_factor, n, timeout=1.0)
    assert not alive, f"largest_prime_factor(2**20) did not finish within 1.0s (O(n) sieve defect)"
    assert "error" not in holder, f"raised {holder.get('error')!r}"
    assert holder.get("value") == 2
